using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using CosineKitty;
namespace NightLens {
class WeatherVerdict {public string Word,Reason;public ConditionLevel Level;public List<string> Reasons=new List<string>();}
class ObservingWeather {
 public Settings S;public Forecast F;public Night N;public DateTime? DarkStart,DarkEnd;public List<Hour> Hours=new List<Hour>();public List<Tuple<DateTime,DateTime>> Moonless=new List<Tuple<DateTime,DateTime>>();public WeatherVerdict Verdict;public int? WorstSeeing,WorstTransparency;
 public ObservingWeather(Settings s,Forecast f,Night n){S=s;F=f;N=n;if(n.Dark.Count>0){DarkStart=SunEvent(Direction.Set,-18)??n.Dark.First();DarkEnd=SunEvent(Direction.Rise,-18)??n.Dark.Last().AddMinutes(10);DateTime first=new DateTime(DarkStart.Value.Year,DarkStart.Value.Month,DarkStart.Value.Day,DarkStart.Value.Hour,0,0,DateTimeKind.Utc);for(DateTime time=first;time<DarkEnd;time=time.AddHours(1)){var value=f.Hours.FirstOrDefault(h=>h.Utc==time);Hours.Add(value??new Hour{Utc=time});}var seeing=n.Dark.Select(t=>f.SeeingAt(t)).Where(v=>v.HasValue).Select(v=>v.Value).ToList();WorstSeeing=seeing.Count==0?(int?)null:seeing.Max();var transparency=n.Dark.Select(t=>f.TransparencyAt(t)).Where(v=>v.HasValue).Select(v=>v.Value).ToList();WorstTransparency=transparency.Count==0?(int?)null:transparency.Max();DateTime? begin=null;foreach(var time in n.Dark){if(n.Altitude(Body.Moon,time)<0){if(!begin.HasValue)begin=time;}else if(begin.HasValue){Moonless.Add(Tuple.Create(begin.Value,time));begin=null;}}if(begin.HasValue)Moonless.Add(Tuple.Create(begin.Value,DarkEnd.Value));}Verdict=Evaluate(Hours);if(DarkStart==null){Verdict=new WeatherVerdict{Word="NO DARK SKY",Reason="No astronomical darkness on this date",Level=ConditionLevel.Unknown};}else if(Verdict.Word=="GO"&&(WorstSeeing>=6||WorstTransparency>=6)){Verdict.Word="MARGINAL";Verdict.Level=ConditionLevel.Medium;Verdict.Reasons.Add(WorstSeeing>=6?"Poor seeing":"Poor transparency");Verdict.Reason=string.Join(" · ",Verdict.Reasons);} }
 public DateTime? SunEvent(Direction direction,double altitude){AstroTime result=altitude==0?Astronomy.SearchRiseSet(Body.Sun,N.Obs,direction,new AstroTime(N.Start),(N.End-N.Start).TotalDays):Astronomy.SearchAltitude(Body.Sun,N.Obs,direction,new AstroTime(N.Start),(N.End-N.Start).TotalDays,altitude);if(result==null)return null;var time=result.ToUtcDateTime();return time>=N.Start&&time<N.End?(DateTime?)time:null;}
 public static WeatherVerdict Evaluate(IEnumerable<Hour> source){var hours=source.ToList();var verdict=new WeatherVerdict{Word="GO",Reason="Forecast within planning limits",Level=ConditionLevel.Good};if(hours.Count==0)return new WeatherVerdict{Word="NO DATA",Reason="No forecast for this window",Level=ConditionLevel.Unknown};double? cloud=Mean(hours,h=>h.Cloud),rain=Max(hours,h=>h.Rain),wind=Max(hours,h=>h.Wind),gust=Max(hours,h=>h.Gust),dew=Min(hours,h=>h.Temp.HasValue&&h.Dew.HasValue?h.Temp-h.Dew:null);double? humidity=Max(hours,h=>h.Humidity);bool poor=cloud>70||rain>=50||wind>=35||gust>=50;bool marginal=cloud>20||rain>=25||wind>=20||gust>=30||dew<=2||humidity>85;if(cloud>20)verdict.Reasons.Add("Cloud cover "+cloud.Value.ToString("0")+"%");if(rain>=25)verdict.Reasons.Add("Rain risk "+rain.Value.ToString("0")+"%");if(wind>=20||gust>=30)verdict.Reasons.Add("Wind above planning limit");if(dew<=2)verdict.Reasons.Add("High dew risk");if(humidity>85)verdict.Reasons.Add("Humidity above 85%");if(poor){verdict.Word="NO-GO";verdict.Level=ConditionLevel.Poor;}else if(marginal){verdict.Word="MARGINAL";verdict.Level=ConditionLevel.Medium;}bool incomplete=hours.Count(h=>h.Cloud.HasValue&&h.Wind.HasValue&&h.Rain.HasValue&&h.Temp.HasValue&&h.Dew.HasValue)<hours.Count*.8;if(incomplete){verdict.Reasons.Add("Incomplete forecast");if(!poor){verdict.Word="LIMITED DATA";verdict.Level=ConditionLevel.Unknown;}}if(verdict.Reasons.Count>0)verdict.Reason=string.Join(" · ",verdict.Reasons);return verdict;}
 public static double? Mean(IEnumerable<Hour> hours,Func<Hour,double?> select){var values=hours.Select(select).Where(v=>v.HasValue).Select(v=>v.Value).ToList();return values.Count==0?(double?)null:values.Average();}
 public static double? Max(IEnumerable<Hour> hours,Func<Hour,double?> select){var values=hours.Select(select).Where(v=>v.HasValue).Select(v=>v.Value).ToList();return values.Count==0?(double?)null:values.Max();}
 public static double? Min(IEnumerable<Hour> hours,Func<Hour,double?> select){var values=hours.Select(select).Where(v=>v.HasValue).Select(v=>v.Value).ToList();return values.Count==0?(double?)null:values.Min();}
 public double? Average(Func<Hour,double?> select){return Mean(Hours,select);}public double? Peak(Func<Hour,double?> select){return Max(Hours,select);}public double? Minimum(Func<Hour,double?> select){return Min(Hours,select);}
 public double? Trend(Func<Hour,double?> select,bool hourly){var values=Hours.Where(h=>select(h).HasValue).OrderBy(h=>h.Utc).ToList();if(values.Count<2)return null;double value=select(values.Last()).Value-select(values.First()).Value;return hourly?value/(values.Last().Utc-values.First().Utc).TotalHours:value;}
 public string Value(double? value,string unit="",string format="0.#"){return value.HasValue?value.Value.ToString(format,CultureInfo.InvariantCulture)+unit:"Not forecast";}
 public string Temp(double? value){return Value(value.HasValue?(double?)(S.Fahrenheit?value.Value*1.8+32:value.Value):null,S.Fahrenheit?" °F":" °C");}
 public string Spread(double? value){return Value(value.HasValue?(double?)(S.Fahrenheit?value.Value*1.8:value.Value):null,S.Fahrenheit?" °F":" °C");}
 public string Wind(double? value){return Value(value.HasValue?(double?)(S.Fahrenheit?value.Value*.621371:value.Value):null,S.Fahrenheit?" mph":" km/h");}
 public string Time(DateTime? value){return value.HasValue?S.Local(value.Value).ToString("ddd h:mm tt"):"None this night";}
 public string HourLabel(DateTime time){var local=S.Local(time);string label=local.ToString("ddd h:mm tt");if(Hours.Count(h=>S.Local(h.Utc)==local)>1){var offset=S.TZ.GetUtcOffset(time);int minutes=(int)Math.Abs(offset.TotalMinutes);label+=" ("+(offset.TotalMinutes<0?"-":"+")+(minutes/60).ToString("00")+":"+(minutes%60).ToString("00")+")";}return label;}
 public string Window {get{return DarkStart.HasValue?S.Local(DarkStart.Value).ToString("h:mm tt")+" – "+S.Local(DarkEnd.Value).ToString("h:mm tt"):"No astronomical darkness";}}
 public string Duration {get{return DarkStart.HasValue?Length(DarkEnd.Value-DarkStart.Value):"0 h";}}
 public static string Length(TimeSpan span){return ((int)span.TotalHours)+"h "+span.Minutes.ToString("00")+"m";}
 public string DewRisk {get{var gap=Minimum(h=>h.Temp.HasValue&&h.Dew.HasValue?h.Temp-h.Dew:null);return !gap.HasValue?"Not forecast":gap<=2?"High":gap<=5?"Medium":"Low";}}
 public string Transparency {get{if(!WorstTransparency.HasValue)return "Not forecast";string[] bins={"","<0.3","0.3–0.4","0.4–0.5","0.5–0.6","0.6–0.7","0.7–0.85","0.85–1",">1"};return (WorstTransparency<=3?"Good":WorstTransparency<=5?"Fair":"Poor")+" · "+bins[WorstTransparency.Value]+" mag/airmass";}}
 public string MoonlessText {get{return !DarkStart.HasValue?"No astronomical darkness":Moonless.Count==0?"None · Moon above horizon during darkness":string.Join("; ",Moonless.Select(w=>S.Local(w.Item1).ToString("h:mm tt")+" – "+S.Local(w.Item2).ToString("h:mm tt")));}}
 public string WindDirection {get{var peak=Hours.Where(h=>h.Wind.HasValue&&h.WindDir.HasValue).OrderByDescending(h=>h.Wind).FirstOrDefault();return peak==null?"Not forecast":ObjectInfo.Compass(peak.WindDir.Value)+" · "+peak.WindDir.Value.ToString("0")+"° (at peak wind)";}}
 public string Fog {get{var gaps=Hours.Where(h=>h.Temp.HasValue&&h.Dew.HasValue&&h.Humidity.HasValue).ToList();return gaps.Count==0?"Not forecast":gaps.Any(h=>h.Temp-h.Dew<=1&&h.Humidity>=95)?"Possible (estimate)":"Low (estimate)";}}
 public string Frost {get{var values=Hours.Where(h=>h.Temp.HasValue&&h.Dew.HasValue).ToList();return values.Count==0?"Not forecast":values.Any(h=>h.Temp<=0&&h.Temp-h.Dew<=2)?"Possible · air-temperature proxy":"Low · air-temperature proxy";}}
}
}
